const m = $input.item.json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const n = (v) => Number(v || 0);
const money = (v) => Math.round(n(v)).toLocaleString('en-US') + ' টাকা';
const top = Array.isArray(m.top_products) ? m.top_products : [];
const low = Array.isArray(m.low_stock) ? m.low_stock : [];
const lines = [];
lines.push('<b>Anfas দৈনিক রিপোর্ট - ' + esc(m.report_date) + '</b>');
lines.push('');
lines.push('<b>মেসেজ ও কমেন্ট</b>');
lines.push('ইনবাউন্ড মেসেজ: ' + n(m.inbound_messages) + ' (কনভারসেশন: ' + n(m.active_conversations) + ')');
lines.push('পাঠানো উত্তর: ' + n(m.replies_sent) + ' | ব্যর্থ: ' + n(m.failed_messages));
lines.push('মানুষের কাছে হস্তান্তর: ' + n(m.escalated_to_human));
lines.push('কমেন্ট হ্যান্ডেল: ' + n(m.comments_handled) + ' | নতুন কাস্টমার: ' + n(m.new_customers));
lines.push('');
lines.push('<b>অর্ডার (ক্যাশ অন ডেলিভারি)</b>');
lines.push('কনফার্মড অর্ডার: ' + n(m.orders_confirmed) + ' | মোট মূল্য: ' + money(m.confirmed_order_value_bdt));
lines.push('পেমেন্ট বাকি: ' + n(m.orders_payment_pending) + ' | পেমেন্ট পাওয়া গেছে: ' + money(m.payments_received_bdt));
lines.push('বাতিল অর্ডার: ' + n(m.orders_cancelled));
if (top.length > 0) {
  lines.push('সেরা পণ্য: ' + top.map((t) => esc(t.name) + ' x' + n(t.qty)).join(', '));
}
lines.push('(কনফার্মড COD অর্ডার মানে পেমেন্ট পাওয়া নয়)');
lines.push('');
lines.push('<b>কনটেন্ট</b>');
lines.push('পাবলিশ হয়েছে: ' + n(m.posts_published) + ' | ব্যর্থ: ' + n(m.posts_failed) + ' | রিভিউয়ের অপেক্ষায়: ' + n(m.drafts_awaiting_review));
lines.push('');
lines.push('<b>সিস্টেম</b>');
lines.push('ওয়ার্কফ্লো এরর: ' + n(m.workflow_errors) + ' | অমীমাংসিত: ' + n(m.unresolved_errors) + ' | ব্যর্থ ওয়েবহুক: ' + n(m.failed_webhook_events));
if (low.length > 0) {
  lines.push('');
  lines.push('<b>কম স্টক</b>');
  lines.push(low.map((p) => esc(p.name) + ' (' + n(p.stock) + ')').join(', '));
}
const metrics = Object.assign({}, m);
delete metrics.report_date;
return { json: { report_date: m.report_date, metrics: metrics, report_text: lines.join('\n') } };
